#pragma once
#include <algorithm>
#include <array>
#include <cstdint>

namespace fssm::parse::ds2 {
    // Generated by tools/ds2_items/gen_items.py (StatTables.cpp).
    // Souls needed to go from level i to level i + 1 (PlayerLevelUpSoulsParam).
    extern const std::array<uint32_t, 851> LEVEL_UP_SOULS;
    // Max equip load for Vitality 1..99, index = Vitality - 1
    // (PhysicalStatsPerLevelStatValuesParam +0x08). Ring bonuses are not included.
    extern const std::array<float, 99> EQUIP_LOAD_BY_VITALITY;

    inline uint32_t soulsToNextLevel(uint32_t level) {
        return level < LEVEL_UP_SOULS.size() ? LEVEL_UP_SOULS[level] : 0;
    }

    inline float equipLoadForVitality(uint32_t vitality) {
        if (vitality == 0) return 0.0f;
        return EQUIP_LOAD_BY_VITALITY[std::min<size_t>(vitality, EQUIP_LOAD_BY_VITALITY.size()) - 1];
    }
}
